      },
      {
        "group": "건강",
        "class_code": "HH_EYE_DMG",
        "category": "1",
        "raw": "심한 눈 손상성/눈 자극성 : 구분1",
        "line": "p1:L27"
      },
      {
        "group": "건강",
        "class_code": "HH_SKIN_SENS",
        "category": "1",
        "raw": "피부 과민성 : 구분1",
        "line": "p1:L28"
      },
      {
        "group": "환경",
        "class_code": "ENV_AQ_CHRONIC",
        "category": "3",
        "raw": "만성 수생환경 유해성 : 구분3",
        "line": "p1:L29"
      }
    ],
    "signal_word": "위험",
    "pictograms": [
      {
        "code": "GHS05"
      },
      {
        "code": "GHS07"
      }
    ],
    "h_statements": [
      {
        "code": "H290",
        "text": "금속을 부식시킬 수 있음",
        "line": "p1:L35"
      },
      {
        "code": "H302",
        "text": "삼키면 유해함",
        "line": "p2:L1"
      },
      {
        "code": "H314",
        "text": "피부에 심한 화상과 눈에 손상을 일으킴",
        "line": "p2:L2"
      },
      {
        "code": "H317",
        "text": "알레르기성 피부 반응을 일으킬 수 있음",
        "line": "p2:L3"
      },
      {
        "code": "H318",
        "text": "눈에 심한 손상을 일으킴",
        "line": "p2:L4"
      },
      {
        "code": "H412",
        "text": "장기적인 영향에 의해 수생생물에게 유해함",
        "line": "p2:L5"
      }
    ],
    "p_statements": [
      {
        "code": "P234",
        "type": "예방",
        "text": "원래의 용기에만 보관하시오.",
        "line": "p2:L8"
      },
      {
        "code": "P260",
        "type": "예방",
        "text": "가스/미스트/증기/스프레이를(을) 흡입하지 마시오.",
        "line": "p2:L9"
      },
      {
        "code": "P261",
        "type": "예방",
        "text": "가스/미스트/증기/스프레이의 흡입을 피하시오.",
        "line": "p2:L10"
      },
      {
        "code": "P264",
        "type": "예방",
        "text": "취급 후에는 취급부위를 철저히 씻으시오.",
        "line": "p2:L11"
      },
      {
        "code": "P270",
        "type": "예방",
        "text": "이 제품을 사용할 때에는 먹거나, 마시거나 흡연하지 마시오.",
        "line": "p2:L12"
      },
      {
        "code": "P272",
        "type": "예방",
        "text": "작업장 밖으로 오염된 의류를 반출하지 마시오.",
        "line": "p2:L13"
      },
      {
        "code": "P273",
        "type": "예방",
        "text": "환경으로 배출하지 마시오.",
        "line": "p2:L14"
      },
      {
        "code": "P280",
        "type": "예방",
        "text": "보호장갑·보호의·보안경·안면보호구를(을) 착용하시오.",
        "line": "p2:L15"
      },
      {
        "code": "P301+P312",
        "type": "대응",
        "text": "삼켰다면: 불편함을 느끼면 의료기관/의사의 진찰을 받으시오.",
        "line": "p2:L17"
      },
      {
        "code": "P301+P330+P331",
        "type": "대응",
        "text": "삼켰다면 입을 씻어내시오. 토하게 하지 마시오.",
        "line": "p2:L18"
      },
      {
        "code": "P302+P352",
        "type": "대응",
        "text": "피부에 묻으면: 다량의 물로 씻으시오.",
        "line": "p2:L19"
      },
      {
        "code": "P303+P361+P353",
        "type": "대응",
        "text": "피부(또는 머리카락)에 묻으면: 오염된 모든 의류를 즉시 벗으시오. 피부를 물로 씻으시오/샤워하시오.",
        "line": "p2:L20"
      },
      {
        "code": "P304+P340",
        "type": "대응",
        "text": "흡입하면: 신선한 공기가 있는 곳으로 옮기고 호흡하기 쉬운 자세로 안정을 취하시오.",
        "line": "p2:L22"
      },
      {
        "code": "P305+P351+P338",
        "type": "대응",
        "text": "눈에 묻으면: 몇 분간 물로 조심해서 씻으시오. 가능하면 콘택트렌즈를 제거하시오. 계속 씻으시오.",
        "line": "p2:L23"
      },
      {
        "code": "P310",
        "type": "대응",
        "text": "즉시 의료기관/의사의 진찰을 받으시오.",
        "line": "p2:L24"
      },
      {
        "code": "P321",
        "type": "대응",
        "text": "응급처치(눈에 들어갔을 때는 다량의 흐르는 물로 세척, 피부에 접촉했을 때는 다량의 흐르는 물로 세척, 흡입했을 때 신선한 공기로 이동, 먹었을 때 구토를 유발할지에 대하여 의료진의 조언을 구함)를 하시오.",
        "line": "p2:L25"
      },
      {
        "code": "P330",
        "type": "대응",
        "text": "입을 씻어내시오.",
        "line": "p2:L27"
      },
      {
        "code": "P333+P313",
        "type": "대응",
        "text": "피부 자극 또는 홍반이 나타나면: 의학적인 조치/조언을 받으시오.",
        "line": "p2:L28"
      },
      {
        "code": "P362+P364",
        "type": "대응",
        "text": "오염된 의류를 벗고 다시 사용 전 세척하시오.",
        "line": "p2:L29"
      },
      {
        "code": "P363",
        "type": "대응",
        "text": "다시 사용전 오염된 의류를 세척하시오.",
        "line": "p2:L30"
      },
      {
        "code": "P390",
        "type": "대응",
        "text": "물질손상을 방지하기 위해 누출물을 흡수시키시오.",
        "line": "p2:L31"
      },
      {
        "code": "P405",
        "type": "저장",
        "text": "잠금장치를 하여 저장하시오.",
        "line": "p2:L33"
      },
      {
        "code": "P406",
        "type": "저장",
        "text": "금속부식성 물질이므로 제조자 또는 행정관청에서 정한 내부식성 용기 등에 보관하시오.",
        "line": "p2:L34"
      },
      {
        "code": "P501",
        "type": "폐기",
        "text": "폐기물 관련 법령에 따라 내용물/용기를 폐기하시오.",
        "line": "p2:L36"
      }
    ],
    "nfpa": {
      "health": 3,
      "fire": 0,
      "reactivity": 2,
      "special": "W"
    },
    "lines": {
      "signal_word": "p1:L33",
      "pictograms": "p1:L31",
      "nfpa": "p1:L37"
    }
  },
  "narratives": [
    {
      "item_code": "S2_LABEL_NOTE",
      "title_raw": "다. 유해성·위험성 분류기준에 포함되지 않는 기타 유해성·위험성",
      "start": "p1:L37",
      "end": "p1:L37"
    }
  ],
  "extras": [
    {
      "after_item": "S2_LABEL_NOTE",
      "title_raw": "다. 유해성·위험성 분류기준에 포함되지 않는 기타 유해성·위험성",
      "reason": "코드없음",
      "statements": [
        {
          "value": "자료없음",
          "line": "p2:L38"
        }
      ]
    ,
    "line": "p2:L38"
  }
]
}

